WFJ.Data.add("gossip", {
  ["ec025dba376dedd8"] = { "Il diario di Jandice Barov è pieno di farneticazioni e deliri sui non morti. Verso la fine del libro c'è quello che sembra un modello di sartoria per creare una Felcloth Bag. Gli stregoni usano questa borsa per conservare i frammenti d'anima. Vuoi copiare il modello nel tuo diario?", "." },
  ["ec04ee06dadf4b20"] = { "L'⟦Alliance=Alleanza⟧ ha preso il ⟦Stonehearth Bunker=Fortilizio di Cordipietra⟧!", "." },
  ["ec055306b4a7e6b0"] = { "Ce l'hai il sapta, <fratello/sorella>?\n\nConosco un altro che ha avuto problemi dopo aver sconfitto lo spirito dell'acqua corrotto: pare che abbia aspettato troppo e sia uscito dal mondo degli spiriti troppo presto pe' i suoi gusti. Non vorrei che succedesse a qualcun altro, quindi aspetterò qui ancora un po' per essere sicuro che nessun altro abbia bisogno del mio aiuto.", "." },
  ["ec0a7fc7d2f3daf8"] = { "Curate le ferite dei feriti, sorelle!", "." },
  ["ec0adc78b51f9f42"] = { "Non vengono molti conciatori qui in cerca di addestramento, ma credo di poterti insegnare qualcosa, se te la senti.", "." },
  ["ec0c47d8f2393da2"] = { "Eccomi!", "." },
  ["ec12e21f3b9c1c98"] = { "Cosa posso fare per te?", "." },
  ["ec15cd69e926bad5"] = { "Cosa? Ma come? No! Non è possibile! Ho fatto così attenzione... non poteva saperlo!\n\nMenti! Menti, e ora morirai per il tuo inganno!", "." },
  ["ec2e6a3763077e1e"] = { "Chi controlla il ⟦Stonehearth Graveyard=Cimitero di Cordipietra⟧?", "." },
  ["ec363f0f323d4961"] = { "Salute, {class}: se cerchi articoli in cuoio e forniture per la lavorazione del cuoio, sei nel posto giusto: questa è la bottega di chi ha lasciato quasi del tutto la vita da Paladino.", "." },
  ["ec3e14f327e739cb"] = { "Noi conosce lei bene. Lei Mary Edras nell'anello interno del ⟦Rogues' Quarter=Quartiere dei Ladri⟧.", "." },
  ["ec4ae0c81f1036f6"] = { "%s si riscuote dal suo delirio.", "." },
  ["ec509ed11c25509d"] = { "Parlami ancora della forgiatura delle armi.", "." },
  ["ec5a069dfc189794"] = { "Boh. Tu cosa vuoi fare?", "." },
  ["ec5a6b1021abd151"] = { "Cos'è l'armatura del Predatore di Cripte?", "." },
  ["ec5db068f17c5fd9"] = { "Che gli spiriti siano con te.", "." },
  ["ec5e830f300e9116"] = { "⟦Fluffy=Morbidino⟧! ⟦Fluffy=Morbidino⟧, smettila di correre!", "." },
  ["ec6644b0ff61684b"] = { "Ti piace il tappeto? Ho ucciso e scuoiato la bestia con le mie mani. Possano tutti i centauri cadere con la stessa facilità.", "." },
  ["ec69ab2f09c48f3e"] = { "Il quartiermastro dei Piccatonante tiene le sue provviste sotto una tettoia, poco a ovest di qui.", "." },
  ["ec75aec630af6fec"] = { "%s riempie un contenitore con la tossina.", "." },
  ["ec7c9ed51b0fc866"] = { "Benvenut<o/a> alle corse! Divertiti, e non puntare tutti i tuoi soldi nello stesso posto!", "." },
  ["ec8772658ba7576a"] = { "%s tracanna la birra!", "." },
  ["ec8c1c7a3d803e76"] = { "{name}! Che ci fai qui a parlare con me? Dovresti essere là fuori a combattere l'⟦Horde=Orda⟧!\n\nHo ordini d'assalto per uno dei nostri marescialli di campo nel ⟦Field of Strife=Pian della Discordia⟧, ma mi serve qualcuno su cui poter contare.\n\nForse, se la tua reputazione presso la milizia dei Piccatonante fosse più alta, potrei contare su di te...", "." },
  ["ec8f1052661006bd"] = { "Ehi, {class}, come butta?", "." },
  ["ec960058d7ad2e61"] = { "Mi serve un Rilevatore Cenariano.", "." },
  ["ec96b95bd8459e90"] = { "Vivo solo per servire il nostro re.", "." },
  ["ec9e2f366325bce5"] = { "Non vedo l'ora di sentire cos'ha da dire un orco così arrabbiato...", "." },
  ["eca0c2fd11e71040"] = { "Grazie. Speriamo che non ce ne siano altri.", "." },
  ["eca326e1e644fc53"] = { "\"E così ha inizio, padre Cenarius. E così ha inizio.\"\n\nDendrite traccia nell'aria sopra di sé un gesto rapido e invisibile. Una lieve aura di potere scende su di lui.\n\n\"La prima prospettiva della natura a cui devi adattarti è quella dell'orso. Ti avvierò sulla strada per comprendere questo aspetto della vita druidica, ma sei tu che devi abbracciarlo e diffonderlo, ora e per sempre!\"", "." },
  ["eca969df24856432"] = { "%s lancia uno strillo acuto, chiedendo aiuto!", "." },
  ["eca969ec2485643f"] = { "%s lancia uno strillo acuto, chiedendo aiuto.", "." },
  ["ecad8b5cf1cceac3"] = { "Cosa sai dirmi della fiera della notte Shadumbra?", "." },
  ["ecb65cd1c5f98213"] = { "Proprio così. La madre della covata dello Stormo dei Draghi Neri aveva usato illusioni e inganni per travestirsi da membro della corte reale. Peggio ancora, aveva preso il controllo dell'attuale gran signore di ⟦Stormwind=Roccavento⟧, Bolvar Fordragon.\n\nNon c'è da stupirsi che fossero state prese decisioni militari così sciocche. Gli ultimi movimenti delle forze dell'⟦Alliance=Alleanza⟧ ci avevano lasciati perplessi. Ora capiamo che lo Stormo dei Draghi Neri cercava di dividere l'impero, di distruggerlo dall'interno.", "." },
  ["ecb7559d040cb7ff"] = { "⟦Thorium Brotherhood=Fratellanza del Torio⟧ o no, se uno di quei ⟦Dark Iron=Ferroscuro⟧ mi si avvicina, assaggerà il mio piccone sulla tempia! Allora, dove posso mandarti, <ragazzo/ragazza>?", "." },
  ["eccb14a675bfef8e"] = { "Come un gatto bagnato dalla pioggia, graffi e artigli, e poi da capo... Tornerò per averne ancora...\n\nOh, non ti avevo <visto/vista> entrare, {name}! Cosa posso fare per te?", "." },
  ["ecd012815144b9b7"] = { "Uccidi, UCCIDI! Riprendi manufatto! Porta a Kartak!", "." },
  ["ecd045df8a2fd869"] = { "Mai mettersi contro un Nano!", "." },
  ["ecda2a459aa04733"] = { "%s sembra preso in contropiede. Si concede qualche istante per riprendersi dalle ferite.", "." },
  ["ecda2d9128888aaa"] = { "I mezzorsi Mordilegno.", "." },
  ["ece56bfcd5437302"] = { "Certo, Capoguerra!", "." },
  ["ece653c6a9f4b26e"] = { "Di cosa hai bisogno?", "." },
  ["ecebb83dfd086b20"] = { "Abbiamo quasi tutto il silithyst che ci serve! Non fermarti adesso!", "." },
  ["ecefd6be1fff1199"] = { "Voglio vedere i tuoi fuochi d'artificio.", "." },
  ["ecf02a5437b85780"] = { "Stanno bene, signore. Dovrebbero riprendersi tutti completamente.", "." },
  ["ecfb0b2e7c38eb70"] = { "Guardati le spalle, <straniero/straniera>.", "." },
  ["ecfda1984eeb5758"] = { "Le rune di protezione sono state distrutte! Date la caccia agli infedeli, fratelli miei!", "." },
